using System;using System.Data;using System.Text;public partial class AdminUsers:System.Web.UI.Page{public string usersHtml="";protected void Page_Load(object sender,EventArgs e){if(Session["userType"]==null||Session["userType"].ToString()!="Admin"){Response.Redirect("Home.aspx");return;}string where=" WHERE 1=1 ";if(Page.IsPostBack){string u=MyAdoHelper.FixText(Request.Form["userName"]),n=MyAdoHelper.FixText(Request.Form["fullName"]),k=MyAdoHelper.FixText(Request.Form["nickName"]);if(u!="")where+=" AND UserName LIKE N'%"+u+"%'";if(n!="")where+=" AND (FirstName LIKE N'%"+n+"%' OR LastName LIKE N'%"+n+"%')";if(k!="")where+=" AND NickName LIKE N'%"+k+"%'";}DataTable dt=MyAdoHelper.ExecuteDataTable("SELECT UserId,FirstName,LastName,UserName,NickName,UserType,Coins FROM Users"+where);StringBuilder s=new StringBuilder("<table class='dataTable'><tr><th>ID</th><th>שם</th><th>שם משתמש</th><th>כינוי</th><th>סוג</th><th>מטבעות</th></tr>");for(int i=0;i<dt.Rows.Count;i++)s.Append("<tr><td>"+dt.Rows[i]["UserId"]+"</td><td>"+dt.Rows[i]["FirstName"]+" "+dt.Rows[i]["LastName"]+"</td><td>"+dt.Rows[i]["UserName"]+"</td><td>"+dt.Rows[i]["NickName"]+"</td><td>"+dt.Rows[i]["UserType"]+"</td><td>"+dt.Rows[i]["Coins"]+"</td></tr>");s.Append("</table>");usersHtml=s.ToString();}}